import { readdirSync, statSync } from 'node:fs'
import path from 'node:path'
import { describe, expect, it } from 'vitest'
import { hasShortCodeShape, isReservedShortCode, RESERVED_SHORT_CODES } from '@/lib/shortCodes'

const APP_DIR = path.resolve(__dirname, '../../app')

// Next.js metadata files generated by code, served without an extension
// (opengraph-image.tsx answers /opengraph-image).
const METADATA_ROUTE_FILES = new Set([
  'apple-icon', 'icon', 'manifest', 'opengraph-image', 'robots', 'sitemap', 'twitter-image',
])

// Every top-level name a request path can reach without hitting [shortCode]:
// route folders, plus code-generated metadata routes. A plain module such as
// fonts.ts is not a route. Static files such as favicon.ico keep their
// extension in the URL, and a dot can never be part of a short code, so they
// cannot collide.
function topLevelRouteNames(): string[] {
  return readdirSync(APP_DIR).flatMap((entry) => {
    const full = path.join(APP_DIR, entry)
    if (statSync(full).isDirectory()) {
      // [shortCode] is the catch-all itself, (group) folders add no segment,
      // and _folders are private.
      return /^[[(_]/.test(entry) ? [] : [entry]
    }
    const match = entry.match(/^(.+)\.(tsx?|jsx?)$/)
    return match && METADATA_ROUTE_FILES.has(match[1]) ? [match[1]] : []
  })
}

describe('RESERVED_SHORT_CODES', () => {
  it('covers every top-level route in src/app', () => {
    const missing = topLevelRouteNames().filter((name) => !RESERVED_SHORT_CODES.has(name))
    expect(missing).toEqual([])
  })

  it('only holds names a custom code could actually take', () => {
    for (const name of RESERVED_SHORT_CODES) {
      expect(name).toMatch(/^[a-z0-9-]+$/)
    }
  })
})

describe('isReservedShortCode', () => {
  it('matches regardless of case and surrounding space', () => {
    expect(isReservedShortCode('dashboard')).toBe(true)
    expect(isReservedShortCode('Dashboard')).toBe(true)
    expect(isReservedShortCode(' login ')).toBe(true)
  })

  it('leaves ordinary codes alone', () => {
    expect(isReservedShortCode('yt')).toBe(false)
    expect(isReservedShortCode('dash')).toBe(false)
    expect(isReservedShortCode('aB3xY9')).toBe(false)
  })
})

describe('hasShortCodeShape', () => {
  it('accepts generated and custom codes', () => {
    expect(hasShortCodeShape('aB3xY9')).toBe(true)
    expect(hasShortCodeShape('yt-live')).toBe(true)
    expect(hasShortCodeShape('a'.repeat(50))).toBe(true)
  })

  it('rejects paths that cannot be a stored code', () => {
    for (const path of ['favicon.ico', 'robots.txt', 'wp-login.php', '.env', 'a_b', 'a b', '', 'a'.repeat(51)]) {
      expect(hasShortCodeShape(path)).toBe(false)
    }
  })
})
